$root = 'C:\Users\USER\akademi-olahraga'
Get-ChildItem -LiteralPath $root -Recurse -File | Where-Object { $_.FullName -notmatch 'chrome-profile|prof-' } | ForEach-Object { "{0,8}  {1}" -f $_.Length, $_.FullName.Substring($root.Length + 1) }
"---"
$proto = Join-Path $root 'prototype'
$brokenTotal = 0
Get-ChildItem -Path $proto -Filter *.html | ForEach-Object {
  $text = Get-Content -Raw -LiteralPath $_.FullName
  $links = [regex]::Matches($text, '(?:href|src)="([^"]+)"') | ForEach-Object { $_.Groups[1].Value }
  foreach ($l in $links) {
    if ($l -match '^(https?:|#|mailto:|data:)' -or $l -eq '') { continue }
    $path = $l.Split('#')[0]
    if ($path -eq '') { continue }
    if (-not (Test-Path -LiteralPath (Join-Path $_.DirectoryName $path))) { "BROKEN: $($_.Name) -> $l"; $brokenTotal++ }
  }
}
if ($brokenTotal -eq 0) { "All local links OK" }
"---"
if (Test-Path (Join-Path $proto '_probe.html')) { 'WARNING: probe file left behind' } else { 'No temp files' }
"---"
